// Cloudinary signing with Web Crypto only, so it runs in Convex's default
// runtime and in the Node migration script without the Cloudinary SDK.
// Algorithms follow the official SDK; cloudinary.test.ts pins them against
// vectors generated by cloudinary@2.11.0.
//
// Mammograms are uploaded as `type: authenticated`: the asset has no public
// URL, and every delivery URL carries a signature only the server can make.

export type CloudinaryConfig = { cloudName: string; apiKey: string; apiSecret: string }

export const UPLOAD_TYPE = 'authenticated'
export const ALLOWED_FORMATS = 'jpg,jpeg,png,tif,tiff,dcm'

async function digest(algorithm: 'SHA-1', input: string): Promise<Uint8Array> {
  const bytes = new TextEncoder().encode(input)
  return new Uint8Array(await crypto.subtle.digest(algorithm, bytes))
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('')
}

function toBase64(bytes: Uint8Array): string {
  let binary = ''
  for (const b of bytes) binary += String.fromCharCode(b)
  return btoa(binary)
}

/** Signature for Upload API params: sorted `k=v` pairs joined by `&`, plus the secret. */
export async function signParams(
  params: Record<string, string | number | undefined>,
  apiSecret: string,
): Promise<string> {
  const toSign = Object.keys(params)
    .filter(k => params[k] !== undefined && params[k] !== '')
    .sort()
    .map(k => `${k}=${params[k]}`)
    .join('&')
  return toHex(await digest('SHA-1', toSign + apiSecret))
}

/**
 * The Upload API response carries a signature over public_id and version.
 * Checking it proves the asset really was uploaded to our account, so a client
 * can't register an arbitrary public_id against a case.
 */
export async function verifyUploadResponse(
  res: { public_id: string; version: number | string; signature: string },
  apiSecret: string,
): Promise<boolean> {
  const expected = await signParams({ public_id: res.public_id, version: res.version }, apiSecret)
  return timingSafeEqual(expected, res.signature)
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false
  let diff = 0
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i)
  return diff === 0
}

/** Signed delivery URL for an authenticated asset. */
export async function signedDeliveryUrl(
  config: CloudinaryConfig,
  asset: { publicId: string; version: number; resourceType: string; format?: string; transformation?: string },
): Promise<string> {
  const source = asset.format ? `${asset.publicId}.${asset.format}` : asset.publicId
  const toSign = [asset.transformation, source].filter(Boolean).join('/')
  const hash = toBase64(await digest('SHA-1', toSign + config.apiSecret))
  const signature = `s--${hash.replace(/\//g, '_').replace(/\+/g, '-').slice(0, 8)}--`
  return [
    `https://res.cloudinary.com/${config.cloudName}`,
    asset.resourceType,
    UPLOAD_TYPE,
    signature,
    asset.transformation,
    `v${asset.version}`,
    source,
  ]
    .filter(Boolean)
    .join('/')
}

/**
 * Format to deliver in. Browsers can't render DICOM, so DICOM image assets are
 * converted to JPEG on delivery; everything else is served as uploaded.
 */
export function deliveryFormat(resourceType: string, storedFormat: string | undefined): string | undefined {
  if (resourceType !== 'image') return undefined // raw assets keep their extension in the public_id
  if (storedFormat === 'dcm') return 'jpg'
  return storedFormat
}

export function caseFolder(caseId: string): string {
  return `bossom/cases/${caseId}`
}
